```csharp
// Include the M5Stack library
#include <M5Stack.h>

// Set the LED pin
#define LED_PIN M5_PIN_2

void setup() {
  // Initialize the M5Stack library
  M5Stack.begin();

  // Turn on the LED
  digitalWrite(LED_PIN, HIGH);
}

void loop() {
  // Nothing to do in the loop
}
```

